stylesheets.stylesheet:
/* ─── I-Forge Theme — Dark Variant ─── */
:root {
  --color-bg: #0d1117;
  --color-surface: #161b22;
  --color-surface-hover: #1c2128;
  --color-accent: #e2b714;
  --color-accent-hover: #f0c940;
  --color-text: #f0f6fc;
  --color-text-secondary: #8b949e;
  --color-border: #30363d;
  --color-divider: #21262d;
  --color-danger: #f85149;
  --color-success: #3fb950;
  --color-t1: #58a6ff;
  --color-t2: #a371f7;
  --color-t3: #f0883e;
  --font-display: Georgia, 'Palatino Linotype', serif;
  --font-body: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
  --font-mono: 'Menlo', 'Consolas', 'Monaco', monospace;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --navbar-height: 60px;
  --content-max: 1200px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.5);
}
img.icon { width: 16px; height: 16px; vertical-align: middle; }
* { margin: 0; padding: 0; box-sizing: border-box; }
/* ─── Force override MyBB defaults ─── */
html, body {
  background: #0d1117 !important;
  background-image:
    radial-gradient(ellipse 80% 60% at 50% -20%, rgba(226, 183, 20, 0.03) 0%, transparent 60%),
    radial-gradient(ellipse 60% 50% at 80% 80%, rgba(48, 54, 61, 0.08) 0%, transparent 50%),
    url('https://i.imgur.com/9lVReZ1.jpeg') !important;
  background-size: auto, auto, cover !important;
  background-position: 0 0, 0 0, center !important;
  background-repeat: repeat, repeat, no-repeat !important;
  background-attachment: fixed !important;
  color: var(--color-text) !important;
  font-family: var(--font-body) !important;
}
body {
  padding-top: var(--navbar-height);
  min-height: 100vh;
  line-height: 1.6;
  position: relative;
}
a { color: var(--color-accent) !important; text-decoration: none; transition: color 0.15s; }
a:hover { color: var(--color-accent-hover) !important; }
img { max-width: 100%; height: auto; }

/* ─── Override MyBB default backgrounds ─── */
#content, .content, #container, .container, .tborder, .tcat, .thead, .trow1, .trow2, tbody, .panel, .post, .post_content, .postbit, #posts, .pagination, .forumdisplay, .threadlist, .wrapper, #main, #wrapper {
  background: transparent !important;
  background-color: transparent !important;
  border-color: var(--color-border) !important;
}
.tcat, .thead {
  background: rgba(22, 27, 34, 0.8) !important;
  color: var(--color-accent) !important;
  border-bottom: 1px solid var(--color-border) !important;
}
.tborder {
  border: 1px solid var(--color-border) !important;
}
#iforge-navbar {
  position: fixed; top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(22, 27, 34, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
  height: var(--navbar-height);
}
.iforge-nav {
  max-width: var(--content-max); margin: 0 auto;
  display: flex; align-items: center;
  justify-content: center;
  height: 100%; padding: 0 var(--space-lg);
  position: relative;
}
.iforge-nav-left {
  display: flex; align-items: center;
  gap: var(--space-xl);
}
.iforge-nav-logo {
  position: absolute;
  left: var(--space-lg);
  font-family: var(--font-display);
  font-size: 1.3rem; font-weight: 700;
  color: var(--color-accent); letter-spacing: 3px;
  text-transform: uppercase;
  border: none;
  padding: 0;
}
.iforge-nav-logo:hover { color: var(--color-accent-hover); }
.iforge-nav-link {
  color: var(--color-text-secondary); font-size: 0.88rem;
  font-weight: 500; padding: 6px 0;
  letter-spacing: 0.5px; transition: color 0.15s;
  position: relative;
}
.iforge-nav-link:hover { color: var(--color-text); }
.iforge-nav-link::after {
  content: '';
  position: absolute; bottom: -2px; left: 0; right: 0;
  height: 2px; background: var(--color-accent);
  transform: scaleX(0); transition: transform 0.2s;
}
.iforge-nav-link:hover::after { transform: scaleX(1); }
.iforge-nav-right {
  position: absolute;
  right: var(--space-lg);
}
.iforge-user-menu { position: relative; }
.iforge-user-btn {
  background: none; border: 2px solid var(--color-border);
  border-radius: 50%; width: 38px; height: 38px;
  cursor: pointer; display: flex; align-items: center;
  justify-content: center; color: var(--color-text-secondary);
  transition: border-color 0.15s, color 0.15s;
}
.iforge-user-btn:hover { border-color: var(--color-accent); color: var(--color-accent); }
.iforge-dropdown {
  display: none; position: absolute; right: 0; top: 48px;
  background: var(--color-surface); border: 1px solid var(--color-border);
  border-radius: var(--radius-md); min-width: 200px;
  box-shadow: var(--shadow-lg); overflow: hidden;
}
.iforge-dropdown.open { display: block; }
.iforge-dropdown-item {
  display: block; padding: 10px var(--space-md);
  color: var(--color-text-secondary); font-size: 0.88rem;
  transition: background 0.15s, color 0.15s;
}
.iforge-dropdown-item:hover { background: var(--color-surface-hover); color: var(--color-text); }
.iforge-dropdown-divider { border: none; border-top: 1px solid var(--color-border); margin: 4px 0; }
#iforge-banner {
  position: relative; width: 100%;
  height: 400px; overflow: hidden;
  background-size: cover; background-position: center;
  display: flex; align-items: center; justify-content: center;
}
#iforge-banner::after {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(13,17,23,0.3) 0%, rgba(13,17,23,0.7) 100%);
}
.iforge-banner-seal {
  position: absolute; z-index: 1;
  color: rgba(226,183,20,0.06); font-size: 280px;
  pointer-events: none;
  font-family: var(--font-display);
  user-select: none;
}

.iforge-banner-content { position: relative; z-index: 2; text-align: center; }
.iforge-banner-title {
  font-family: var(--font-display); font-size: 3.5rem;
  font-weight: 700; color: var(--color-text);
  letter-spacing: 8px; margin-bottom: var(--space-sm);
  text-shadow: 0 2px 16px rgba(0,0,0,0.5);
  text-transform: uppercase;
}
.iforge-banner-subtitle {
  font-size: 1.1rem; color: var(--color-accent);
  letter-spacing: 4px; font-weight: 400;
}
#iforge-calendar-bar {
  display: flex; align-items: center; justify-content: center;
  gap: var(--space-sm); padding: 12px var(--space-lg);
  background: rgba(22, 27, 34, 0.9);
  border-bottom: 1px solid var(--color-border);
  font-size: 0.85rem; color: var(--color-text-secondary);
  letter-spacing: 0.5px;
}
#iforge-calendar-bar .icon { width: 14px; height: 14px; opacity: 0.6; }
#iforge-calendar-bar strong { color: var(--color-text); }
.iforge-tablon {
  max-width: var(--content-max); margin: 0 auto;
  padding: var(--space-xl) var(--space-lg) 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-md);
}
.iforge-card {
  background: rgba(22, 27, 34, 0.6);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  backdrop-filter: blur(4px);
  transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;
}
.iforge-card:hover {
  border-color: var(--color-accent);
  box-shadow: 0 0 16px rgba(226, 183, 20, 0.06);
  background: rgba(22, 27, 34, 0.8);
}
.iforge-card-header {
  padding: 10px var(--space-md);
  font-size: 0.68rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 1.8px; color: var(--color-accent);
  border-bottom: 1px solid var(--color-border);
  background: rgba(226, 183, 20, 0.04);
  display: flex; align-items: center; gap: var(--space-sm);
}
.iforge-card-header .icon {
  width: 14px; height: 14px;
  color: var(--color-accent); opacity: 0.7; flex-shrink: 0;
}
.iforge-card-body {
  padding: var(--space-sm) 0;
  min-height: 60px;
  display: flex; flex-direction: column;
}
.iforge-card-body:empty::after {
  content: 'Aún no hay mensajes — el mundo espera tu historia.';
  display: block;
  padding: var(--space-lg) var(--space-md);
  color: var(--color-text-secondary);
  font-size: 0.85rem;
  font-style: italic;
  text-align: center;
}
.iforge-card-item {
  display: block; padding: 10px var(--space-md);
  color: var(--color-text); font-size: 0.88rem;
  transition: background 0.15s;
  border-bottom: 1px solid var(--color-divider);
}
.iforge-card-item:last-child { border-bottom: none; }
.iforge-card-item:hover { background: rgba(255,255,255,0.03); }
.iforge-card-item-meta {
  font-size: 0.75rem; color: var(--color-text-secondary); margin-top: 3px;
  display: flex; align-items: center; gap: var(--space-xs);
}
.iforge-card-more {
  display: block; padding: 8px var(--space-md);
  text-align: center; font-size: 0.78rem;
  border-top: 1px solid var(--color-divider);
  color: var(--color-text-secondary); letter-spacing: 0.5px;
  transition: background 0.15s, color 0.15s;
  margin-top: auto;
}
.iforge-card-more:hover { background: rgba(255,255,255,0.03); color: var(--color-accent); }
.iforge-staff-section {
  grid-column: 1 / -1;
  background: rgba(22, 27, 34, 0.6);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  backdrop-filter: blur(4px);
}
.iforge-staff-section:hover {
  border-color: var(--color-accent);
}
.iforge-staff-list {
  display: flex; flex-wrap: wrap; gap: var(--space-sm);
  padding: var(--space-md);
}
.iforge-staff-item {
  display: flex; align-items: center; gap: var(--space-sm);
  padding: 8px 14px;
  background: rgba(255,255,255,0.03);
  border: 1px solid var(--color-divider);
  border-radius: var(--radius-sm);
  font-size: 0.85rem;
  transition: border-color 0.15s, background 0.15s;
}
.iforge-staff-item:hover {
  border-color: var(--color-border);
  background: var(--color-surface-hover);
}
.iforge-staff-item .icon { width: 18px; height: 18px; }
.iforge-staff-name { color: var(--color-text); font-weight: 500; }
.iforge-staff-mp {
  color: var(--color-text-secondary); font-size: 0.72rem;
  margin-left: var(--space-xs); padding: 2px 8px;
  border: 1px solid var(--color-divider);
  border-radius: var(--radius-sm);
  transition: color 0.15s, border-color 0.15s;
}
.iforge-staff-mp:hover { color: var(--color-accent); border-color: var(--color-accent); }
.iforge-categories {
  max-width: var(--content-max); margin: 0 auto;
  padding: var(--space-lg);
  display: flex; flex-direction: column; gap: var(--space-md);
}
.iforge-category-card {
  position: relative; border-radius: var(--radius-lg);
  overflow: hidden; cursor: pointer;
  min-height: 120px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s;
  display: block;
}
.iforge-category-card:hover {
  border-color: var(--color-accent);
  box-shadow: 0 0 24px rgba(226,183,20,0.08);
  transform: translateY(-2px);
}
.iforge-category-card::before {
  content: '';
  position: absolute; inset: 0;
  background: linear-gradient(135deg, rgba(13,17,23,0.88) 0%, rgba(13,17,23,0.55) 100%);
  z-index: 0;
}
.iforge-category-card:hover::before {
  background: linear-gradient(135deg, rgba(13,17,23,0.72) 0%, rgba(13,17,23,0.4) 100%);
}
.iforge-category-seal {
  position: absolute; right: var(--space-lg); top: 50%;
  transform: translateY(-50%);
  color: rgba(226,183,20,0.06); font-size: 100px;
  pointer-events: none;
  z-index: 0;
  font-family: var(--font-display);
  user-select: none;
}

.iforge-category-content {
  position: relative; z-index: 1;
  padding: var(--space-xl) var(--space-xl);
  display: flex; align-items: center; gap: var(--space-lg);
}
.iforge-category-icon-wrap {
  width: 44px; height: 44px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--color-divider);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  background: rgba(255,255,255,0.02);
}
.iforge-category-icon {
  width: 22px; height: 22px;
  color: var(--color-accent);
}
.iforge-category-text { flex: 1; }
.iforge-category-title {
  font-family: var(--font-display); font-size: 1.3rem;
  font-weight: 700; color: var(--color-text); margin-bottom: var(--space-xs);
  letter-spacing: 0.5px;
}
.iforge-category-desc {
  color: var(--color-text-secondary); font-size: 0.85rem;
  max-width: 500px; line-height: 1.5;
}
.iforge-category-arrow {
  color: var(--color-border);
  width: 20px; height: 20px;
  transition: color 0.2s, transform 0.2s;
  flex-shrink: 0;
}
.iforge-category-card:hover .iforge-category-arrow {
  color: var(--color-accent);
  transform: translateX(4px);
}
#iforge-curiosidad {
  padding: var(--space-md);
  font-size: 0.88rem; color: var(--color-text-secondary);
  font-style: italic; line-height: 1.7;
  min-height: 50px;
}
#iforge-curiosidad::before {
  content: '✦';
  color: var(--color-accent);
  margin-right: var(--space-sm);
  font-style: normal;
}
#iforge-next-curiosidad {
  cursor: pointer; color: var(--color-accent);
  display: inline-block; margin-top: var(--space-sm);
  font-size: 0.78rem; font-style: normal;
  letter-spacing: 0.5px; opacity: 0.7;
  transition: opacity 0.15s;
}
#iforge-next-curiosidad:hover { opacity: 1; }
#iforge-footer {
  background: rgba(22, 27, 34, 0.9);
  border-top: 1px solid var(--color-border);
  padding: var(--space-xl) var(--space-lg);
  text-align: center;
  color: var(--color-text-secondary); font-size: 0.78rem;
  display: flex; align-items: center; justify-content: center;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}
#iforge-footer .seal {
  width: 20px; height: 20px;
  opacity: 0.4;
}
.iforge-badge {
  display: inline-block; padding: 2px 8px;
  border-radius: 10px; font-size: 0.65rem;
  font-weight: 600; margin-right: var(--space-xs);
  letter-spacing: 0.3px;
}
.iforge-badge-t1 { background: rgba(88,166,255,0.15); color: #58a6ff; }
.iforge-badge-t2 { background: rgba(163,113,247,0.15); color: #a371f7; }
.iforge-badge-t3 { background: rgba(240,136,62,0.15); color: #f0883e; }
/* ─── Decorative Elements ─── */
.iforge-card, .iforge-category-card, .iforge-staff-section {
  position: relative;
}
.iforge-card::before, .iforge-category-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, rgba(226,183,20,0.15) 0%, transparent 30%, transparent 70%, rgba(226,183,20,0.1) 100%);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.3s;
}
.iforge-card:hover::before, .iforge-category-card:hover::before {
  opacity: 1;
}
.iforge-card-header::after {
  content: '';
  position: absolute;
  bottom: 0; left: var(--space-md); right: var(--space-md);
  height: 1px;
  background: linear-gradient(90deg, transparent 0%, var(--color-accent) 50%, transparent 100%);
  opacity: 0.3;
}
.iforge-card-header {
  position: relative;
}
#index {
  background: transparent !important;
}
#container, .container, #content {
  background: transparent !important;
}
.trow1, .trow2, tbody tr {
  background: transparent !important;
}

@media (max-width: 768px) {
  .iforge-tablon { grid-template-columns: 1fr; }
  .iforge-nav-logo { font-size: 1.1rem; letter-spacing: 2px; }
  .iforge-nav-left { gap: var(--space-md); }
  .iforge-nav-link { font-size: 0.8rem; }
  .iforge-banner-title { font-size: 2rem; letter-spacing: 4px; }
  #iforge-banner { height: 260px; }
  .iforge-banner-seal { font-size: 160px; }
  .iforge-category-card { min-height: 100px; }
  .iforge-category-content { padding: var(--space-lg); flex-direction: column; align-items: flex-start; gap: var(--space-sm); }
  .iforge-category-title { font-size: 1.1rem; }
  .iforge-category-icon-wrap { width: 36px; height: 36px; }
  .iforge-category-icon { width: 18px; height: 18px; }
}
